  @moduledoc """
  Verifies the vendored Affidavit engine: admits the vendored bytes through
  `AshAffidavit.EngineLoad.admit/2`, starts a real `AshAffidavit.Host`, sends the `capabilities` op and
  requires the reported `abi_version` to equal the manifest `abi_version`. A passing run is an
  observation about these bytes; it grants nothing.
  """

  use Mix.Task

  alias AshAffidavit.EngineLoad
  alias AshAffidavit.Host
  alias AshAffidavit.Refusal

  @doc """
  Runs the task. Returns `:ok`; raises `Mix.Error` with a `[code]` prefix on refusal.
  """
  @impl Mix.Task
  @spec run([String.t()]) :: :ok
  def run(_argv) do
    Mix.Task.run("app.start")
    dir = priv_dir()
    manifest = read_manifest!(Path.join(dir, "MANIFEST.json"))
    artifact = manifest["artifact"]
    path = Path.join(dir, artifact["file"])
    expected = manifest["abi_version"]

    bytes =
      case File.read(path) do
        {:ok, bytes} -> bytes
        {:error, reason} -> fail("wasm_not_vendored", "#{path}: #{inspect(reason)}; run mix ash_affidavit.vendor")
      end

    admitted =
